package io.github.easy4j.dingtalk.spring.boot.autoconfigure.properties;

import java.util.List;

import lombok.Data;
import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * Configuration properties for DingTalk integration, bound to the {@code dingtalk}
 * application prefix.  All application-specific sub-configurations are expressed as
 * nested static classes here (never imported from the pure SDK), matching the
 * WxJava "properties + nested configs" pattern so that Spring metadata is fully
 * generated by the annotation processor.
 *
 * @author <a href="https://github.com/loong10k">Loong Wan</a>
 * @since 1.0.0
 */
@ConfigurationProperties(prefix = DingTalkProperties.PREFIX)
@Data
public class DingTalkProperties {

    public static final String PREFIX = "dingtalk";

    /** The enterprise corpId (全局企业 corpId). */
    private String corpId;

    /** The enterprise corpSecret (全局企业 secret，内部应用用). */
    private String corpSecret;

    /** Internal enterprise application (H5 / mini program) list. */
    private List<CorpApp> corpApps;
    /** Personal / third-party mini-app list. */
    private List<PersonalMiniApp> apps;
    /** Suite / ISV enterprise application list. */
    private List<Suite> suites;
    /** Mobile scan-to-login application list. */
    private List<Login> logins;
    /** Robot list (custom-service chatbots). */
    private List<Robot> robots;

    /** Config for a single internal enterprise application (钉钉自建应用). */
    @Data
    public static class CorpApp {
        private String agentId;
        private String appKey;
        private String appSecret;
    }

    /** Config for a single personal / third-party mini application. */
    @Data
    public static class PersonalMiniApp {
        private String appId;
        private String appSecret;
    }

    /** Config for a single suite / ISV application. */
    @Data
    public static class Suite {
        private String suiteId;
        private String appId;
        private String suiteKey;
        private String suiteSecret;
    }

    /** Config for a single mobile-login application (扫码登录 / 免登). */
    @Data
    public static class Login {
        private String appId;
        private String appSecret;
    }

    /** Config for a single custom-service (群机器人) robot. */
    @Data
    public static class Robot {
        private String robotId;
        private String accessToken;
        private String secretToken;
    }
}
